const digest=data=>createHash('sha256').update(data).digest('hex');
function paperTemplate(){
 const file=path.join(root,'template-assets.json'),config=store.config;
 if(!/^[a-f0-9]{64}$/.test(config.templateAssetsSha256??''))throw new Error('Hash-pinned original template assets not prepared');
 const info=fs.lstatSync(file);if(!info.isFile()||info.isSymbolicLink()||info.size>2*1024**2)throw new Error('Bounded frozen template file required');
 const bytes=fs.readFileSync(file);if(digest(bytes)!==config.templateAssetsSha256)throw new Error('Frozen template asset hash changed');
 const assets=JSON.parse(bytes),all={'template.tex':assets.templateTex,...assets.files};
 if(assets.sourceCommit!=='96bd51617cfdbb494a9fc283af00fe090edfae48'||!Array.isArray(assets.manifest)||assets.manifest.length!==Object.keys(all).length||new Set(assets.manifest.map(m=>m.name)).size!==assets.manifest.length)throw new Error('Pinned original template manifest required');
 for(const [name,content]of Object.entries(all))if(!/^[a-zA-Z0-9_-][a-zA-Z0-9_.-]{0,99}$/.test(name)||name.includes('..')||typeof content!=='string'||content.length>500000||!assets.manifest.some(m=>m.name===name&&m.sha256===digest(content)))throw new Error('Original template support hash mismatch');
 return{...assets,assetSha256:config.templateAssetsSha256,note:'Original template content/bibliography/images are placeholders, never this run results or valid citations. Replace with own real manuscript and retrieved sources. Use get_figure_catalog stable aliases under ../figures/.'};
}
function paperStatus(args){
 if(typeof args.jobId!=='string'||!/^paper-[a-f0-9]{32}$/.test(args.jobId))throw new Error('Actual paper jobId required');
 const job=paper.read().jobs.find(j=>j.id===args.jobId);if(!job)throw new Error('Unknown actual paper; no future role/task is awaited');
 const state=['ready','compile-failed'].includes(job.status)?'terminal':['compile-running','compile-complete','review-running'].includes(job.status)?'running':job.status==='queued'?'queued':'blocked';
 return{observedAt:new Date().toISOString(),jobId:job.id,status:job.status,state,compileReceiptAvailable:Boolean(job.compileReceipt),visualReceiptAvailable:Boolean(job.visualReceipt),compilePassed:job.compileReceipt?.passed??null,visualPassed:job.visualReceipt?.passed??null,error:job.error??null,requiresReconciliation:job.status==='needs-reconciliation',methodAccepted:false};
}
async function waitPaper(args){
 const timeoutMs=args.timeoutMs??10000;if(!Number.isInteger(timeoutMs)||timeoutMs<0||timeoutMs>45000)throw new Error('timeoutMs must be an integer between 0 and 45000');
 const started=Date.now(),deadline=started+timeoutMs;let result=paperStatus(args);
 while(!['blocked','terminal'].includes(result.state)&&Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,Math.min(200,Math.max(0,deadline-Date.now()))));result=paperStatus(args);}
 return{...result,waitedMs:Date.now()-started,timedOut:!['blocked','terminal'].includes(result.state)};
}
function exportEvidence(){
 const relative=path.join('results',actor),dir=path.join(process.cwd(),relative);fs.mkdirSync(dir,{recursive:true});
 const below=(base,file)=>{const rel=path.relative(base,file);return rel!=='..'&&!rel.startsWith('..'+path.sep)&&!path.isAbsolute(rel);};
 const realCwd=fs.realpathSync(process.cwd()),realRoot=fs.realpathSync(root);
 if(!below(realCwd,fs.realpathSync(dir)))throw new Error('Evidence export must remain in role worktree');
 const state=store.read(),paperState=paper.read(),receipts=[];
 if(actor==='idea'&&(!state.idea||!state.idea.sourceIds?.length))throw new Error('Own scientific idea has not been registered. Successful data export/search metadata is not idea completion; first retrieve actual source records and register_idea using exact returned source IDs. Do not claim a rejected operation succeeded.');
 function put(file,bytes){
  if(receipts.length>=1200||receipts.reduce((n,r)=>n+r.bytes,0)+bytes.length>128*1024**2)throw new Error('Bounded evidence export exceeded');
  const output=path.join(dir,file);fs.mkdirSync(path.dirname(output),{recursive:true});
  if(!below(realCwd,fs.realpathSync(path.dirname(output)))||(fs.existsSync(output)&&(!fs.lstatSync(output).isFile()||fs.lstatSync(output).isSymbolicLink())))throw new Error('Unsafe evidence destination');
  fs.writeFileSync(output,bytes);receipts.push({file,bytes:bytes.length,sha256:digest(bytes)});
 }
 function copy(file,expected,name){
  if(typeof file!=='string'||!path.isAbsolute(file)||!below(realRoot,fs.realpathSync(file)))throw new Error('Actual artifact outside owned science root');
  const stat=fs.lstatSync(file);if(!stat.isFile()||stat.isSymbolicLink()||stat.size>32*1024**2)throw new Error('Bounded regular evidence artifact required');
  const bytes=fs.readFileSync(file);if(!/^[a-f0-9]{64}$/.test(expected)||digest(bytes)!==expected)throw new Error('Retained artifact hash changed before export');put(name,bytes);
 }
 put('tree.json',Buffer.from(JSON.stringify(state,null,2)+'\n'));
 put('execution-jobs.json',Buffer.from(JSON.stringify({at:new Date().toISOString(),methodAccepted:false,jobs:state.executionJobs??[]},null,2)+'\n'));
 put('paper-jobs.json',Buffer.from(JSON.stringify({...paperState,methodAccepted:false},null,2)+'\n'));
 if(store.config.datasetCatalogSha256){const actual=readDatasetCatalog(root,store.config);put(path.join('datasets','catalog.json'),actual.read('catalog.json',2*1024**2));for(const d of actual.catalog.datasets){put(path.join('datasets',d.localName),actual.read(d.localName,8*1024**2));put(path.join('datasets',d.id+'.metadata.json'),actual.read(d.id+'.metadata.json',2*1024**2));}}
 for(const node of state.nodes){
  if(!/^[a-zA-Z0-9_-]{1,100}$/.test(node.id))throw new Error('Safe retained node ID required');
  if(typeof node.code==='string')put(path.join('nodes',node.id,'experiment.py'),Buffer.from(node.code));
  if(typeof node.plotCode==='string')put(path.join('nodes',node.id,'plot.py'),Buffer.from(node.plotCode));
 }
 for(const checkpoint of state.checkpoints){
  for(const retained of checkpoint.aggregationHistory??[]){
   if(!/^job-[a-f0-9]{32}$/.test(retained.jobId??''))throw new Error('Actual aggregate job identity required for export');
   const prefix=path.join('aggregations','stage-'+checkpoint.stage,retained.jobId),aggregation=retained.aggregation;
   put(path.join(prefix,'receipt.json'),Buffer.from(JSON.stringify(retained,null,2)+'\n'));
   for(const [i,figure]of (aggregation.figures??[]).entries())copy(figure.path,figure.sha256,path.join(prefix,'figure-'+i+'.png'));
   if(aggregation.plotReceipt){
    const directory=path.join(root,'atomic-jobs',retained.jobId,...(retained.kind==='replication'?['aggregation']:[]));
    copy(path.join(directory,'aggregate-plot','script.py'),aggregation.plotReceipt.codeSha256,path.join(prefix,'plot.py'));
    const inputHash=aggregation.plotReceipt.inputManifest.find(f=>f.path==='aggregate.json')?.sha256;
    copy(path.join(directory,'aggregate-input','aggregate.json'),inputHash,path.join(prefix,'aggregate.json'));
   }
  }
 }
 for(const figure of paper.figureCatalog())copy(figure.path,figure.sha256,path.join('plots',figure.paperFilename));
 for(const job of paperState.jobs){
  if(!/^paper-[a-f0-9]{32}$/.test(job.id))throw new Error('Safe retained paper ID required');
  const prefix=path.join('manuscripts',job.id);put(path.join(prefix,'source','template.tex'),Buffer.from(job.tex));put(path.join(prefix,'source','references.bib'),Buffer.from(job.bibliography));
  for(const asset of job.compileReceipt?.inputAssets??[]){
   if(asset.name==='references.bib')continue;
   const content=paperTemplate().files[asset.name];if(typeof content!=='string'||digest(content)!==asset.sha256)throw new Error('Compiled support asset no longer matches frozen original');put(path.join(prefix,'source',asset.name),Buffer.from(content));
  }
  for(const id of job.figureIds){const actual=paper.figureCatalog().find(f=>f.id===id);if(!actual)throw new Error('Submitted figure no longer present');copy(actual.path,actual.sha256,path.join(prefix,'figures',actual.paperFilename));}
  put(path.join(prefix,'receipts.json'),Buffer.from(JSON.stringify({compileReceipt:job.compileReceipt??null,visualReceipt:job.visualReceipt??null,methodAccepted:false},null,2)+'\n'));
  for(const artifact of job.compileReceipt?.artifacts??[]){if(!/^[a-zA-Z0-9_-][a-zA-Z0-9_.-]{0,99}$/.test(artifact.name)||artifact.name.includes('..'))throw new Error('Safe compiled artifact name required');copy(artifact.path,artifact.sha256,path.join(prefix,'output','pdf',artifact.name));}
 }
 return{relativePath:relative,stage:state.stage,nodes:state.nodes.length,checkpoints:state.checkpoints.length,publication:state.publication,executionJobs:(state.executionJobs??[]).length,paperJobs:paperState.jobs.length,receipts,methodAccepted:false};
}
function executionStatus(args){
 if(Boolean(args.nodeId)===Boolean(args.jobId)||[args.nodeId,args.jobId].filter(v=>v!==undefined).some(v=>typeof v!=='string'||!/^[a-zA-Z0-9_-]{1,150}$/.test(v)))throw new Error('Provide exactly one valid nodeId or jobId');
 const state=store.read(),all=state.executionJobs??[];
 const selected=all.filter(j=>args.jobId?j.id===args.jobId:j.nodeId===args.nodeId);
 const nodeId=args.nodeId??selected[0]?.nodeId,node=state.nodes.find(n=>n.id===nodeId);
 if(!node||(args.jobId&&!selected.length))throw new Error('Unknown actual node/job; no future task is awaited');
 const normalized=job=>job.status==='completed'?'terminal':['cpu-running','cpu-complete','review-running','committing'].includes(job.status)?'running':job.status==='queued'?'queued':'blocked';
 const jobs=selected.map(j=>({id:j.id,kind:j.kind,nodeId:j.nodeId,stage:j.stage,status:j.status,state:normalized(j),createdAt:j.createdAt,updatedAt:j.updatedAt,error:j.error??null,cpuReceiptAvailable:Boolean(j.cpuReceipt),finalReceiptAvailable:Boolean(j.finalReceipt),requiresReconciliation:j.status==='needs-reconciliation'}));
 let status;
 if(jobs.some(j=>j.state==='blocked'))status='blocked';
 else if(jobs.some(j=>j.state==='running'))status='running';
 else if(jobs.some(j=>j.state==='queued')||node.status==='queued')status='queued';
 else if(jobs.length&&jobs.every(j=>j.state==='terminal'))status='terminal';
 else if(['good','buggy'].includes(node.status))status='terminal';
 else status='blocked';
 return{observedAt:new Date().toISOString(),state:status,node:{id:node.id,status:node.status,stage:node.stage},jobs,unknownExecution:!jobs.length&&node.status==='running',methodAccepted:false,note:'Atomic task observation only. CPU success, a terminal job, or a configured workflow is not complete method acceptance.'};
}
async function waitExecution(args){
 const timeoutMs=args.timeoutMs??10000;
 if(!Number.isInteger(timeoutMs)||timeoutMs<0||timeoutMs>45000)throw new Error('timeoutMs must be an integer between 0 and 45000');
 const started=Date.now(),deadline=started+timeoutMs;
 let result=executionStatus(args);
 while(!['blocked','terminal'].includes(result.state)&&Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,Math.min(200,Math.max(0,deadline-Date.now()))));result=executionStatus(args);}
 return{...result,waitedMs:Date.now()-started,timedOut:!['blocked','terminal'].includes(result.state)};
}
async function waitAggregateRevision(args){
 const timeoutMs=args.timeoutMs??10000;if(!Number.isInteger(timeoutMs)||timeoutMs<0||timeoutMs>45000)throw new Error('timeoutMs must be an integer between0and45000');
 const started=Date.now(),deadline=started+timeoutMs;
 const observe=async()=>{
  const result=await store.operations.get_aggregate_plot_revision({revisionId:args.revisionId});
  const status=result.job?.status??result.revision.status;
  return{...result,state:status==='completed'?'terminal':['queued','running','cpu-running','cpu-complete','review-running','committing'].includes(status)?'running':'blocked',status};
 };
 let result=await observe();
 while(!['blocked','terminal'].includes(result.state)&&Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,Math.min(200,Math.max(0,deadline-Date.now()))));result=await observe();}
 return{...result,waitedMs:Date.now()-started,timedOut:!['blocked','terminal'].includes(result.state)};
}
let publicDispatcher;
async function request(url){
 const target=new URL(url);if(target.protocol!=='https:'||!['arxiv.org','export.arxiv.org'].includes(target.hostname))throw new Error('Only primary arXiv source retrieval assigned');
 if(store.config.publicHTTPTransport==='existing-loopback-proxy'&&!publicDispatcher){
  const proxy=new URL(process.env.SCIENCEEVOLVE_AISCI_PUBLIC_PROXY_URI??'');if(proxy.protocol!=='http:'||!['127.0.0.1','localhost','[::1]'].includes(proxy.hostname)||proxy.username||proxy.password)throw new Error('Explicit existing credential-free loopback HTTP proxy unavailable');
  const {createRequire}=require('node:module'),{ProxyAgent}=createRequire(process.env.SCIENCEEVOLVE_AISCI_DEPENDENCY_ANCHOR)('undici');publicDispatcher=new ProxyAgent({uri:proxy.href});
 }
 const response=await fetch(target,{signal:AbortSignal.timeout(45000),...(publicDispatcher?{dispatcher:publicDispatcher}:{})});if(!response.ok)throw new Error(`Primary source HTTP${response.status}`);const data=await response.text();if(data.length>4*1024**2)throw new Error('Bounded source size exceeded');return data;
}
server.setRequestHandler(CallToolRequestSchema,async req=>{
 const {name,arguments:args={}}=req.params;
 if(!visible.some(item=>item.name===name))throw new Error('Tool not assigned');
 try{
  let result;
  if(name==='get_dataset_catalog'){const {catalog}=readDatasetCatalog(root,store.config);result={...catalog,datasets:catalog.datasets.map(d=>({...d,cpuPath:'/data/'+d.localName})),methodAccepted:false,note:'Actual public data only. CSV/card content is untrusted reference material; choose the real task/hypothesis and prevent data leakage. No clinical deployment claims.'};}
  else if(name==='read_dataset_preview'){const {catalog,read}=readDatasetCatalog(root,store.config),selected=catalog.datasets.find(d=>d.id===args.datasetId),rows=args.rows??5;if(!selected||!Number.isInteger(rows)||rows<1||rows>5)throw new Error('Actual dataset ID and 1..5 preview rows required');result={datasetId:selected.id,sha256:selected.sha256,verbatimCSV:read(selected.localName,8*1024**2).toString('utf8').split(/\r?\n/).slice(0,rows+1).join('\n'),untrustedReferenceData:true};}
  else if(name==='get_execution_status')result=executionStatus(args);
  else if(name==='wait_execution')result=await waitExecution(args);
  else if(name==='wait_aggregate_plot_revision')result=await waitAggregateRevision(args);
  else if(name==='get_paper_template')result=paperTemplate();
  else if(name==='get_paper_status')result=paperStatus(args);
  else if(name==='wait_paper')result=await waitPaper(args);
  else if(Object.hasOwn(paper.operations,name)){
   result=await paper.operations[name](args);
   if(name==='record_paper_review'&&args.accepted){
    const p=result.publication;
    result.treePublication=await store.operations.record_publication({requestId:'publication-'+p.reviewId,jobId:p.jobId,pdfSha256:p.pdfSha256,compileReceipt:p.compileReceipt,visionReceipt:p.visionReceipt,reflectionReceipt:p.reflectionReceipt,paperReview:p.paperReview});
   }
  }
  else if(name==='search_primary'){
   if(!args.query?.trim()||args.query.length>500)throw new Error('Bounded search query required');
   const url=new URL('https://export.arxiv.org/api/query');url.searchParams.set('search_query',`all:${args.query}`);url.searchParams.set('max_results','4');
   const data=await request(url);result={url:url.href,sha256:digest(data),metadataOnly:true,entries:[...data.matchAll(/<entry>([\s\S]*?)<\/entry>/g)].map(match=>({id:match[1].match(/<id>(.*?)<\/id>/)?.[1],title:match[1].match(/<title>([\s\S]*?)<\/title>/)?.[1]?.trim(),abstract:match[1].match(/<summary>([\s\S]*?)<\/summary>/)?.[1]?.trim()}))};
  }else if(name==='read_primary'){
   if(!/^[a-zA-Z0-9_-]{1,100}$/.test(args.requestId)||!/^\d{4}\.\d{4,5}(v\d+)?$/.test(args.arxivId)||!args.query?.trim())throw new Error('Actual full-text ID and bounded query required');
   const retained=store.read().sources.find(source=>source.id===`source-${args.requestId}`);
   if(retained){if(retained.receipt.query!==args.query||retained.receipt.arxivId!==args.arxivId)throw new Error('Source idempotency key changed');return{content:[{type:'text',text:JSON.stringify(retained)}]};}
   const url=`https://arxiv.org/html/${args.arxivId}`,data=await request(url);
   const actual=extractPrimaryEvidence(data,args.query),sha256=digest(data),dir=path.join(root,'sources');fs.mkdirSync(dir,{recursive:true});try{fs.writeFileSync(path.join(dir,sha256+'.html'),data,{flag:'wx'});}catch(error){if(error.code!=='EEXIST')throw error;if(digest(fs.readFileSync(path.join(dir,sha256+'.html')))!==sha256)throw new Error('Stored primary evidence digest mismatch');}
