// Atomic method-state contract; research choices are made by SDK Agents.
// This module is NOT an AI-Scientist launcher or a substitute for real execution.
const fs = require('node:fs');
const path = require('node:path');
const { createHash } = require('node:crypto');
const { DatabaseSync } = require('node:sqlite');
const hash = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');
const idOK = value => typeof value === 'string' && /^[a-zA-Z0-9_-]{1,100}$/.test(value);
// Request IDs are caller-owned provenance, not filesystem/CPU node identities.
// Preserve legacy short names; hash only when the actor namespace would exceed
// the shared 100-character node contract. Never ask the model to guess this ID.
function candidateId(actor,requestId){
  if(!['worker_a','worker_b'].includes(actor)||!idOK(requestId))throw new Error('Assigned actor and valid request ID required');
  const readable=`${actor}-${requestId}`;
  return idOK(readable)?readable:`${actor}-${hash({actor,requestId})}`;
}
const stages = ['preliminary', 'hyperparameter', 'research', 'ablation'];
// Transport/I/O contract only: no scientific code, prescribed algorithm or result.
// Return this with every actual reservation so it is not hidden in a long role prompt.
const executionContract = {
  version: 1,
  identity:'Use the exact reservation.id/nodeId returned by the tool; do not derive it by concatenating an Agent name and requestId. Long requests retain sourceRequestId but use a bounded opaque node identity.',
  experiment: {language:'python',entrypoint:'/work/script.py',execution:'The submitted code is executed as __main__, not called as a function.',dataRoot:'/data',outputRoot:'/output',seedEnvironment:'SCIENCEEVOLVE_SEED',seedRule:'Use exactly int(os.environ["SCIENCEEVOLVE_SEED"]) for this single atomic job. The host separately runs three winner replicas.',metricsFile:'/output/metrics.json',metricsSchema:{seed:'exact current integer SCIENCEEVOLVE_SEED',datasets:[{id:'unique actual dataset ID',metrics:{actual_named_metric:'finite number'}}]},datasetCount:{minimum:1,maximum:30},diagnostics:'Additional arrays/folds/curves belong in separate flat JSON/CSV/NPY output files, not the numeric metrics map. stdout, a return value and /tmp files do not replace metrics.json.'},
  plot: {language:'python',entrypoint:'/work/script.py',execution:'A separate container runs plotCode after the experiment has passed the metrics contract.',inputRoot:'/input',metricsFile:'/input/metrics.json',outputRoot:'/output',figures:'Write 1..20 genuine PNG figures to /output. The read-only /input contains retained experiment output files; it is not the dataset directory in this phase.'},
  acceptance:'Successful process exit is not scientific/visual/method acceptance. No invented measurements, fixtures or copied replica results.'
};
function openTree(root, actor) {
  if (!path.isAbsolute(root) || !['main','idea','manager','worker_a','worker_b','writer','reflector','reviewer','evaluator'].includes(actor)) throw new Error('Explicit root and assigned actor required');
  const config = JSON.parse(fs.readFileSync(path.join(root,'settings.json'),'utf8'));
  if (config.method !== 'ai-scientist-v2' || config.numSeeds !== 3 || config.numDrafts !== 3 || config.debugProbability !== .5 || config.maxDebugDepth !== 3) throw new Error('Method constants are not configured');
  const aggregatePlotRepairLimit=config.aggregatePlotRepairLimit??3;
  if(!Number.isInteger(aggregatePlotRepairLimit)||aggregatePlotRepairLimit<1||aggregatePlotRepairLimit>3)throw new Error('Explicit aggregate plot repair budget must be 1..3');
  const db = new DatabaseSync(path.join(root,'tree.sqlite'));
  db.exec('PRAGMA busy_timeout=5000');
  for (let attempt=0;;attempt++) {
    try { if (db.prepare('PRAGMA journal_mode').get().journal_mode !== 'wal') db.exec('PRAGMA journal_mode=WAL'); db.exec('CREATE TABLE IF NOT EXISTS state(id INTEGER PRIMARY KEY,json TEXT NOT NULL);CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY,requestHash TEXT,json TEXT);'); break; }
    catch (error) { if (![5,6].includes(error.errcode) || attempt >= 80) { db.close(); throw error; } Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,25); }
  }
  db.prepare('INSERT OR IGNORE INTO state(id,json) VALUES (1,?)').run(JSON.stringify({ stage:0, nodes:[], reservations:[], ranks:[], checkpoints:[], sources:[], idea:null, publication:null, revision:0 }));
  const read = () => JSON.parse(db.prepare('SELECT json FROM state WHERE id=1').get().json);
  const must = allowed => { if (!allowed.includes(actor)) throw new Error('Tool is not assigned to this role'); };
  function mutate(name, args, fn) {
    if (!idOK(args.requestId)) throw new Error('Stable requestId required');
    const id = `${actor}:${name}:${args.requestId}`, digest = hash(args);
    db.exec('BEGIN IMMEDIATE');
    try {
      const retained = db.prepare('SELECT * FROM receipts WHERE id=?').get(id);
      if (retained) { if (retained.requestHash !== digest) throw new Error('Idempotency key changed'); db.exec('COMMIT'); return JSON.parse(retained.json); }
      const state = read(), result = fn(state); state.revision++;
      db.prepare('UPDATE state SET json=? WHERE id=1').run(JSON.stringify(state));
      db.prepare('INSERT INTO receipts(id,requestHash,json) VALUES (?,?,?)').run(id,digest,JSON.stringify(result)); db.exec('COMMIT'); return result;
    } catch (error) { db.exec('ROLLBACK'); throw error; }
  }
  const nodeSummary = ({code,plotCode,...node}) => node;
  const checkpointSummary=c=>({...c,aggregationPlotRevisions:(c.aggregationPlotRevisions??[]).map(({plotCode,...r})=>r)});
  const aggregateRepair=state=>{
    const c=state.checkpoints.find(c=>c.stage===state.stage);
