    return {stage:c.stage,nodeId:c.bestNodeId,parentJobId:c.aggregationJobId??null,
      attempts:revisions.length,limit:aggregatePlotRepairLimit,pending,
      repairable:Boolean(negative&&!pending&&revisions.length<aggregatePlotRepairLimit&&c.replications.length===3&&c.replications.every(r=>r.passed)),
      exhausted:Boolean(negative&&!pending&&revisions.length>=aggregatePlotRepairLimit),
      latestStatus:job?.status??null,feedback:c.aggregation?.vision?.feedback??c.aggregation?.error??null,
      inputContract:{file:'/input/aggregate.json',schema:'{seeds, datasets:[{id, metrics:{name:{values,mean,std}}}], stdDefinition, replicationScope}',output:'1..20 genuine PNGs under /output',rule:'Retained measurements only; no new experiment, fabricated baseline or statistical conclusion.'}};
  };
