  };
  const operations = {
    get_tree: async () => { const state=read(); return {...state,nodes:state.nodes.map(nodeSummary),checkpoints:state.checkpoints.map(checkpointSummary),aggregateRepair:aggregateRepair(state),stageName:stages[state.stage],config:{task:config.task,stageBudgets:config.stageBudgets,numSeeds:config.numSeeds,numDrafts:config.numDrafts,debugProbability:config.debugProbability,maxDebugDepth:config.maxDebugDepth,aggregatePlotRepairLimit,executionContract}}; },
    get_node: async ({nodeId}) => { const node=read().nodes.find(item=>item.id===nodeId); if(!node)throw new Error('Unknown actual node');return node; },
    register_source: async args => { must(['idea']); return mutate('source',args,state=>{ if(!args.url?.startsWith('https://')||!args.sha256?.match(/^[a-f0-9]{64}$/)||!args.excerpt?.trim()||!args.retrievalReceipt)throw new Error('Actual retrieval and quotation provenance required');const source={id:`source-${args.requestId}`,url:args.url,sha256:args.sha256,excerpt:args.excerpt,receipt:args.retrievalReceipt};state.sources.push(source);return source;}); },
    register_idea: async args => { must(['idea']);return mutate('idea',args,state=>{ if(state.idea)throw new Error('Selected idea already retained');if(!args.title?.trim()||!args.hypothesis?.trim()||!args.plan?.trim()||!args.sourceIds?.length||args.sourceIds.some(id=>!state.sources.some(source=>source.id===id)))throw new Error('Grounded idea with actual retrieved sources required');state.idea={title:args.title,hypothesis:args.hypothesis,plan:args.plan,sourceIds:args.sourceIds};return state.idea;}); },
    rank_good_nodes: async args => { must(['manager']);return mutate('rank',args,state=>{ const good=state.nodes.filter(node=>node.stage===state.stage&&node.status==='good');if(!good.length||args.ids?.length!==good.length||new Set(args.ids).size!==good.length||args.ids.some(id=>!good.some(node=>node.id===id))||!args.reasoning?.trim())throw new Error('LLM ranking must account for all current non-buggy nodes and explain metrics/curves/plots');const ranking={stage:state.stage,ids:args.ids,reasoning:args.reasoning};state.ranks.push(ranking);return ranking;}); },
    reserve_expansion: async args => { must(['worker_a','worker_b']);return mutate('reserve',args,state=>{
      if(!state.idea||state.stage>3)throw new Error('Grounded idea and active stage required');
      const current=state.reservations.filter(item=>item.stage===state.stage);
      if(current.length>=config.stageBudgets[state.stage])throw new Error('Explicit reduced stage budget exhausted');
      const nodes=state.nodes.filter(item=>item.stage===state.stage);
      const drafts=current.filter(item=>item.mode==='draft');
      const draw=parseInt(hash(`${actor}:${args.requestId}`).slice(0,8),16)/2**32;
      let mode,parent=null;
      const debug=nodes.filter(item=>item.status==='buggy'&&item.debugDepth<=config.maxDebugDepth&&!state.reservations.some(child=>child.parentId===item.id));
      if(state.stage===0&&drafts.length<config.numDrafts)mode='draft';
      else if(draw<config.debugProbability&&debug.length){mode='debug';parent=debug[Math.floor(draw/config.debugProbability*debug.length)];}
      else if([1,3].includes(state.stage)){mode=state.stage===1?'hyperparameter':'ablation';parent=state.nodes.find(node=>node.id===state.checkpoints.at(-1)?.bestNodeId);}
      else {parent=best(state);mode=parent?'improve':'draft';}
