      const reservation={id:candidateId(actor,args.requestId),sourceRequestId:args.requestId,actor,stage:state.stage,mode,parentId:parent?.id??null,debugDepth:mode==='debug'?(parent.debugDepth??0)+1:0,draw,createdAt:new Date().toISOString(),status:'reserved'};
      state.reservations.push(reservation);return{...reservation,idea:state.idea,parent:parent??null,stageName:stages[state.stage],instructions:config.task,executionContract};
    }); },
    submit_node: async args => { must(['worker_a','worker_b']);return mutate('submit',args,state=>{
      const reservation=state.reservations.find(item=>item.id===args.reservationId&&item.actor===actor);
      if(!reservation||reservation.status!=='reserved'||reservation.stage!==state.stage)throw new Error('Current owned reservation required');
      if(!args.code?.trim()||!args.plotCode?.trim()||!args.plan?.trim()||args.code.length>200000||args.plotCode.length>100000)throw new Error('Actual experiment plan, code and plot code required');
      if(['hyperparameter','ablation'].includes(reservation.mode)){
        if(!args.variant?.trim()||state.nodes.some(node=>node.stage===state.stage&&node.variant===args.variant))throw new Error('Unique hyperparameter/ablation description required; duplicates are forbidden');
      }
      const node={...reservation,id:reservation.id,code:args.code,plotCode:args.plotCode,plan:args.plan,variant:args.variant,status:'queued',submittedAt:new Date().toISOString()};state.nodes.push(node);reservation.status='submitted';return{nodeId:node.id,status:'queued'};
    }); },
    choose_checkpoint: async args => { must(['manager']);return mutate('checkpoint',args,state=>{
      const current=state.nodes.filter(node=>node.stage===state.stage),reservation=state.reservations.filter(item=>item.stage===state.stage);
      if(state.checkpoints.some(item=>item.stage===state.stage)||current.some(node=>!['good','buggy'].includes(node.status))||reservation.some(item=>item.status==='reserved'))throw new Error('Stage has unsettled work or an existing checkpoint');
