    }); },
    submit_aggregate_plot_revision: async args=>{must(['manager']);return mutate('aggregate-plot-revision',args,state=>{
      if(Object.keys(args).some(k=>!['requestId','stage','parentJobId','plotCode','reasoning'].includes(k)))throw new Error('Only authored plot code/reasoning allowed; trusted receipts cannot be supplied by Agent');
