    }); },
    publication_status: async () => read().publication,
    record_publication: async args => { must(['reviewer']);return mutate('publication',args,state=>{if(state.stage!==4||!args.pdfSha256?.match(/^[a-f0-9]{64}$/)||!args.paperReview?.trim()||!args.visionReceipt?.passed||!args.reflectionReceipt||!args.compileReceipt?.passed)throw new Error('Compiled paper, reflection, real figure/caption VLM and independent review required');state.publication={...args,recordedAt:new Date().toISOString()};return state.publication;}); }
