      (checkpoint.aggregationHistory??=[]).push({jobId:job.id,revisionId,kind:'aggregation-revision',parentJobId:revision.parentJobId,at:revision.finishedAt,aggregation});return checkpointSummary(checkpoint);
    }),close:()=>db.close() };
}
module.exports={openTree,stages,executionContract,candidateId};

