 const read=(name,limit)=>{if(!safe(name))throw new Error('Safe dataset artifact name required');const file=path.join(directory,name),real=fs.realpathSync(file),relative=path.relative(fs.realpathSync(directory),real),stat=fs.lstatSync(file);if(relative.startsWith('..'+path.sep)||relative==='..'||path.isAbsolute(relative)||!stat.isFile()||stat.isSymbolicLink()||stat.size>limit)throw new Error('Bounded owned regular dataset asset required');return fs.readFileSync(file);};
 const bytes=read('catalog.json',2*1024**2);if(digest(bytes)!==config.datasetCatalogSha256)throw new Error('Frozen dataset catalog hash changed');
 const catalog=JSON.parse(bytes);if(catalog.status!=='ready'||!Array.isArray(catalog.datasets)||catalog.datasets.length<2||catalog.datasets.length>8)throw new Error('Actual bounded dataset catalog required');
 for(const d of catalog.datasets)if(!safe(d.id)||!d.localName?.endsWith('.csv')||!/^[a-f0-9]{40}$/.test(d.revision)||digest(read(d.localName,8*1024**2))!==d.sha256||digest(read(d.id+'.metadata.json',2*1024**2))!==d.metadataSha256)throw new Error('Actual pinned dataset hash mismatch');
