      const node=state.nodes.find(n=>n.id===c.bestNodeId);
      const revision={id:'aggregate-'+hash({actor,requestId:args.requestId,stage:args.stage,parentJobId:args.parentJobId}).slice(0,32),stage:args.stage,parentJobId:args.parentJobId,nodeId:c.bestNodeId,nodeCodeSha256:createHash('sha256').update(node.code).digest('hex'),plotCode:args.plotCode,plotCodeSha256,reasoning:args.reasoning,status:'queued',createdAt:new Date().toISOString()};
