      if(Object.keys(args.patch??{}).some(k=>!allowed.includes(k)))throw new Error('Invalid execution update');
      const active=j=>['cpu-running','review-running','committing'].includes(j.status)||(j.status==='needs-reconciliation'&&!j.cpuReceipt);
