// Private method adapter only. Agents author/reflect/review; the trusted host
// alone writes compiler and VLM receipts. No SDK/core or model client here.
const fs=require('node:fs'),path=require('node:path');
const {createHash}=require('node:crypto'),{DatabaseSync}=require('node:sqlite');
const hash=x=>createHash('sha256').update(JSON.stringify(x)).digest('hex');
const idOK=x=>typeof x==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(x);
const actors=['main','idea','manager','worker_a','worker_b','writer','reflector','reviewer','evaluator'];
function figureCatalog(tree){
 const figures=[];
 const add=(nodeId,stage,kind,items)=>{for(const [index,item]of(items??[]).entries())if(item.path&&/^[a-f0-9]{64}$/.test(item.sha256)){
   const id='plot-'+hash({nodeId,stage,kind,index,sha256:item.sha256}).slice(0,28);
   figures.push({id,paperFilename:id+'.png',nodeId,stage,kind,path:item.path,sha256:item.sha256,...(Number.isInteger(item.bytes)?{bytes:item.bytes}:{})});
 }};
 for(const node of tree.nodes)add(node.id,node.stage,'node',node.evaluation?.figures);
 for(const checkpoint of tree.checkpoints){
   add(checkpoint.bestNodeId,checkpoint.stage,'aggregation',checkpoint.aggregation?.figures);
   for(const replica of checkpoint.replications)add(checkpoint.bestNodeId,checkpoint.stage,'seed-'+replica.seed,replica.figures);
 }
 return figures;
}
function scienceReady(tree){
 return tree.stage===4&&[0,1,2,3].every(stage=>tree.checkpoints.some(c=>c.stage===stage&&c.closedAt&&c.replications.length===3&&new Set(c.replications.map(r=>r.seed)).size===3&&c.replications.every(r=>r.passed&&r.executionReceipt)&&c.aggregation?.vision?.passed));
}
function openPaperStore(root,actor,readTree){
 if(!path.isAbsolute(root)||!actors.includes(actor)||typeof readTree!=='function')throw new Error('Explicit paper root, actor and actual tree reader required');
 const config=JSON.parse(fs.readFileSync(path.join(root,'settings.json'),'utf8'));
 const maxReflections=config.writeupReflections??3;if(maxReflections!==3)throw new Error('Original bounded three-reflection contract required');
 const db=new DatabaseSync(path.join(root,'paper.sqlite'));db.exec('PRAGMA busy_timeout=5000');
 for(let attempt=0;;attempt++)try{
   if(db.prepare('PRAGMA journal_mode').get().journal_mode!=='wal')db.exec('PRAGMA journal_mode=WAL');
   db.exec('CREATE TABLE IF NOT EXISTS state(id INTEGER PRIMARY KEY,json TEXT NOT NULL);CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY,digest TEXT,json TEXT);');
   db.prepare('INSERT OR IGNORE INTO state(id,json) VALUES(1,?)').run(JSON.stringify({jobs:[],reflections:[],reviews:[],publication:null,revision:0}));break;
 }catch(error){if(![5,6].includes(error.errcode)||attempt>=80){db.close();throw error;}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,25);}
 const read=()=>JSON.parse(db.prepare('SELECT json FROM state WHERE id=1').get().json);
 const must=allowed=>{if(!allowed.includes(actor))throw new Error('Paper operation not assigned');};
 function mutate(name,args,fn){
   if(!idOK(args.requestId))throw new Error('Stable paper requestId required');
   const key=actor+':'+name+':'+args.requestId,digest=hash(args);db.exec('BEGIN IMMEDIATE');
   try{
     const prior=db.prepare('SELECT * FROM receipts WHERE id=?').get(key);
     if(prior){if(prior.digest!==digest)throw new Error('Paper idempotency arguments changed');db.exec('COMMIT');return JSON.parse(prior.json);}
     const state=read(),result=fn(state);state.revision++;
     db.prepare('UPDATE state SET json=? WHERE id=1').run(JSON.stringify(state));
     db.prepare('INSERT INTO receipts(id,digest,json) VALUES(?,?,?)').run(key,digest,JSON.stringify(result));db.exec('COMMIT');return result;
   }catch(error){db.exec('ROLLBACK');throw error;}
 }
 const summary=({tex,bibliography,compileReceipt,visualReceipt,...job})=>({...job,compileReceiptAvailable:Boolean(compileReceipt),visualReceiptAvailable:Boolean(visualReceipt),compilePassed:compileReceipt?.passed??null,visualPassed:visualReceipt?.passed??null,pdfSha256:compileReceipt?.pdfSha256??null,pages:compileReceipt?.pages??null});
 const latest=state=>state.jobs.at(-1);
 function submit(state,args,kind){
   const tree=readTree();if(!scienceReady(tree))throw new Error('Four closed real stages and seed/vision evidence required before manuscript');
   if(typeof args.tex!=='string'||!args.tex.trim()||args.tex.length>200000||typeof(args.bibliography??'')!=='string'||(args.bibliography??'').length>50000)throw new Error('Bounded full authored manuscript and bibliography required');
   if(!Array.isArray(args.figureIds)||!args.figureIds.length||args.figureIds.length>20||new Set(args.figureIds).size!==args.figureIds.length||args.figureIds.some(id=>!figureCatalog(tree).some(f=>f.id===id)))throw new Error('Select actual retained figure IDs only');
   const job={id:'paper-'+hash({actor,requestId:args.requestId}).slice(0,32),actor,kind,tex:args.tex,bibliography:args.bibliography??'',figureIds:args.figureIds,status:'queued',createdAt:new Date().toISOString(),
     ...(args.parentJobId?{parentJobId:args.parentJobId}:{}),...(args.reflectionId?{reflectionId:args.reflectionId}:{})};
   state.jobs.push(job);return summary(job);
 }
 const operations={
   get_paper_state:async()=>{const state=read(),p=state.publication;return{...state,jobs:state.jobs.map(summary),publication:p?{jobId:p.jobId,pdfSha256:p.pdfSha256,reviewId:p.reviewId,recordedAt:p.recordedAt,compilePassed:p.compileReceipt.passed,visualPassed:p.visionReceipt.passed,reflectionRound:p.reflectionReceipt.round}:null,scienceReady:scienceReady(readTree()),maxReflections,methodAccepted:false};},
   get_manuscript:async({jobId})=>{const job=read().jobs.find(j=>j.id===jobId);if(!job)throw new Error('Actual paper job missing');return job;},
   get_figure_catalog:async()=>figureCatalog(readTree()),
   submit_manuscript:async args=>{must(['writer']);return mutate('submit',args,state=>{
     const previous=latest(state);
     if(previous){if(previous.actor!=='writer'||!['compile-failed','resource-blocked'].includes(previous.status)||args.parentJobId!==previous.id)throw new Error('Initial writing is single-pass; later changes require reflection or exact failed-compile repair');}
     return submit(state,args,previous?'compiler-repair':'initial-single-pass');
   });},
   record_reflection:async args=>{must(['reflector']);return mutate('reflection',args,state=>{
     const job=latest(state);
     if(!job||job.id!==args.jobId||job.status!=='ready'||!job.compileReceipt?.passed||!job.visualReceipt)throw new Error('Current actual compiled and visually reviewed manuscript required');
     if(state.reflections.length>=maxReflections)throw new Error('Original reflection budget exhausted; independent review final compiled revision, do not add unlimited rounds');
     if(typeof args.done!=='boolean'||!args.assessment?.trim()||args.assessment.length>20000)throw new Error('Actual independent reasoning reflection required');
     if(args.done&&!job.visualReceipt.passed)throw new Error('Cannot declare done over real negative figure/caption feedback');
     if(state.reflections.some(r=>r.jobId===job.id))throw new Error('Current manuscript already reflected; submit the actual revision or proceed with retained done result');
     const result={id:'reflection-'+hash({requestId:args.requestId,jobId:job.id}).slice(0,24),jobId:job.id,round:state.reflections.length+1,done:args.done,assessment:args.assessment,recordedAt:new Date().toISOString()};state.reflections.push(result);return result;
   });},
   submit_revision:async args=>{must(['reflector']);return mutate('revision',args,state=>{
     const job=latest(state),reflection=state.reflections.find(r=>r.id===args.reflectionId);
     const initialRevision=job?.status==='ready'&&reflection?.jobId===job.id;
     const compilerRepair=['compile-failed','resource-blocked'].includes(job?.status)&&job?.kind==='reasoning-reflection-revision'&&job.reflectionId===reflection?.id;
     if(!job||job.id!==args.parentJobId||!reflection||reflection.done||(!initialRevision&&!compilerRepair))throw new Error('Actual unresolved reflection of the current manuscript required');
     return submit(state,args,'reasoning-reflection-revision');
   });},
   record_paper_review:async args=>{must(['reviewer']);return mutate('review',args,state=>{
     const job=latest(state);if(!job||job.id!==args.jobId||job.status!=='ready'||typeof args.accepted!=='boolean'||typeof args.assessment!=='string'||!args.assessment.trim()||args.assessment.length>20000)throw new Error('Current real paper and independent review required');
     const currentDone=state.reflections.find(r=>r.jobId===job.id&&r.done);
     const boundedFinal=state.reflections.length===maxReflections&&job.kind==='reasoning-reflection-revision'&&state.reflections.some(r=>r.id===job.reflectionId&&r.round===maxReflections);
     if(args.accepted&&(!scienceReady(readTree())||!job.compileReceipt?.passed||!job.visualReceipt?.passed||(!currentDone&&!boundedFinal)))throw new Error('Actual stage, compile, visual and independent reflection evidence required; cannot certify a queued/negative/unreflected paper');
     const review={id:'paper-review-'+hash(args).slice(0,24),jobId:job.id,accepted:args.accepted,assessment:args.assessment,recordedAt:new Date().toISOString()};state.reviews.push(review);
     if(args.accepted){if(state.publication)throw new Error('Publication already recorded');state.publication={jobId:job.id,pdfSha256:job.compileReceipt.pdfSha256,compileReceipt:job.compileReceipt,visionReceipt:job.visualReceipt,reflectionReceipt:currentDone??state.reflections.at(-1),paperReview:args.assessment,reviewId:review.id,recordedAt:review.recordedAt};}
     return{review,publication:state.publication};
   });}
 };
 return{read,operations,figureCatalog:()=>figureCatalog(readTree()),
   claim:args=>{must(['evaluator']);return mutate('claim',args,state=>{
     if(state.jobs.some(j=>['compile-running','review-running','needs-reconciliation'].includes(j.status)))return null;
     const job=state.jobs.find(j=>j.status==='queued');if(!job)return null;
     if(!idOK(args.owner)||!Number.isInteger(args.pid)||args.pid<=0)throw new Error('Actual host ownership required');
     job.owner=args.owner;job.pid=args.pid;job.status='compile-running';return job;
   });},
   update:args=>{must(['evaluator']);return mutate('update',args,state=>{
     const job=state.jobs.find(j=>j.id===args.jobId);if(!job||job.owner!==args.expectedOwner||job.status!==args.expectedStatus)throw new Error('Paper ownership/status changed');
     if(Object.keys(args.patch??{}).some(k=>!['status','owner','pid','compileReceipt','visualReceipt','error'].includes(k)))throw new Error('Invalid trusted paper update');
     Object.assign(job,args.patch,{updatedAt:new Date().toISOString()});return job;
   });},close:()=>db.close()};
}
module.exports={openPaperStore,figureCatalog,scienceReady};

