const fs=require('node:fs'),path=require('node:path'),{createHash}=require('node:crypto');
const digest=x=>createHash('sha256').update(x).digest('hex');
const safe=x=>typeof x==='string'&&/^[a-zA-Z0-9_-][a-zA-Z0-9_.-]{0,99}$/.test(x)&&!x.includes('..');
function readDatasetCatalog(root,config){
 if(!/^[a-f0-9]{64}$/.test(config.datasetCatalogSha256??''))throw new Error('Frozen real dataset catalog not prepared');
 const directory=path.join(root,'datasets');
