const idOK=x=>typeof x==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(x);
const actors=['main','idea','manager','worker_a','worker_b','writer','reflector','reviewer','evaluator'];
function figureCatalog(tree){
