   claim:args=>{must(['evaluator']);return mutate('claim',args,state=>{
     if(state.jobs.some(j=>['compile-running','review-running','needs-reconciliation'].includes(j.status)))return null;
     const job=state.jobs.find(j=>j.status==='queued');if(!job)return null;
