// Deterministic extraction of actual downloaded article text. Does not generate
// quotations, verify the user's scientific claim, or treat article text as rules.
function extractPrimaryEvidence(data,query){
 if(typeof data!=='string'||typeof query!=='string'||!query.trim()||query.length>500)throw new Error('Bounded actual HTML and evidence query required');
 if(!/<article\b[^>]*\bclass\s*=\s*['"][^'"]*\bltx_(?:document|article)\b[^'"]*['"]/i.test(data)||!/<section\b[^>]*\bclass\s*=\s*['"][^'"]*\bltx_section\b/i.test(data)||/checking your browser|verify you are human/i.test(data))throw new Error('Actual article sections unavailable; abstract/challenge is not full text');
