 const add=(nodeId,stage,kind,items)=>{for(const [index,item]of(items??[]).entries())if(item.path&&/^[a-f0-9]{64}$/.test(item.sha256)){
   const id='plot-'+hash({nodeId,stage,kind,index,sha256:item.sha256}).slice(0,28);
   figures.push({id,paperFilename:id+'.png',nodeId,stage,kind,path:item.path,sha256:item.sha256,...(Number.isInteger(item.bytes)?{bytes:item.bytes}:{})});
 }};
 for(const node of tree.nodes)add(node.id,node.stage,'node',node.evaluation?.figures);
 for(const checkpoint of tree.checkpoints){
   add(checkpoint.bestNodeId,checkpoint.stage,'aggregation',checkpoint.aggregation?.figures);
   for(const replica of checkpoint.replications)add(checkpoint.bestNodeId,checkpoint.stage,'seed-'+replica.seed,replica.figures);
 }
 return figures;
}
function scienceReady(tree){
 return tree.stage===4&&[0,1,2,3].every(stage=>tree.checkpoints.some(c=>c.stage===stage&&c.closedAt&&c.replications.length===3&&new Set(c.replications.map(r=>r.seed)).size===3&&c.replications.every(r=>r.passed&&r.executionReceipt)&&c.aggregation?.vision?.passed));
