   });},
   record_paper_review:async args=>{must(['reviewer']);return mutate('review',args,state=>{
     const job=latest(state);if(!job||job.id!==args.jobId||job.status!=='ready'||typeof args.accepted!=='boolean'||typeof args.assessment!=='string'||!args.assessment.trim()||args.assessment.length>20000)throw new Error('Current real paper and independent review required');
