// Deterministic extraction of actual downloaded article text. Does not generate
// quotations, verify the user's scientific claim, or treat article text as rules.
function extractPrimaryEvidence(data,query){
 if(typeof data!=='string'||typeof query!=='string'||!query.trim()||query.length>500)throw new Error('Bounded actual HTML and evidence query required');
 if(!/<article\b[^>]*\bclass\s*=\s*['"][^'"]*\bltx_(?:document|article)\b[^'"]*['"]/i.test(data)||!/<section\b[^>]*\bclass\s*=\s*['"][^'"]*\bltx_section\b/i.test(data)||/checking your browser|verify you are human/i.test(data))throw new Error('Actual article sections unavailable; abstract/challenge is not full text');
 const clean=data.replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<style[\s\S]*?<\/style>/gi,'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' '),lower=clean.toLowerCase(),literal=lower.indexOf(query.toLowerCase());
 const title=data.match(/<title>([\s\S]*?)<\/title>/i)?.[1]?.replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim()??null;
 let index=literal,matchingMode='literal-phrase',matchedQueryTerms=[];
 if(index<0){
  const stop=new Set(['the','and','for','with','from','that','this','are','how','why','what']);
  const terms=[...new Set((query.toLowerCase().match(/[a-z][a-z0-9-]{2,}/g)??[]).filter(t=>!stop.has(t)))].slice(0,20);
  const starts=terms.flatMap(term=>{const found=[];for(let cursor=lower.indexOf(term);cursor>=0&&found.length<100;cursor=lower.indexOf(term,cursor+term.length))found.push(cursor);return found;});
  let bestScore=0;
  for(const start of starts){const window=lower.slice(Math.max(0,start-500),start+3000),matched=terms.filter(t=>window.includes(t));if(matched.length>bestScore){bestScore=matched.length;index=start;matchedQueryTerms=matched;}}
  if(index<0)throw new Error('No requested terms found in actual article text; do not fabricate evidence');matchingMode='lexical-window-not-semantic-certification';
 }
 return{title,excerpt:clean.slice(Math.max(0,index-500),index+3000),matchingMode,literalPhraseFound:literal>=0,matchedQueryTerms,note:'Verbatim extracted text only. Matching terms/phrase do not certify the scientific assertion, novelty or complete method.'};
}
module.exports={extractPrimaryEvidence};
